// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    address deployer;

    function setUp() public {
        deployer = address(this);
        c = new Owned();
    }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != deployer);

        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);

        address ownerAfter = c.owner();
        assertTrue(ownerAfter == newOwner);

        address attacker = newOwner;
        address proposed = address(0x123);

        vm.deal(attacker, 1 ether);
        vm.prank(attacker);
        try c.setOwner(proposed) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}
